class NomSalarioEscala extends BaseNomSalarioEscala {

	/**
     * Obtener un listado de grupos escalas que se va a listar sus salarios escalas.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de grupos escalas.
     */
	public static function obtenerGruposEscalasListar($inicio = 0, $limite = 1000) {

		//Devuelve los identificadores de grupos escalas que se van a listar.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->select('idgrupoescala as idgrupoescala')
            ->from('NomSalarioEscala')
            ->groupby('idgrupoescala')
            ->limit($limite)
			->offset($inicio)
            ->fetchArray():
            $query->select('idgrupoescala as idgrupoescala')
            ->from('NomSalarioEscala')
            ->groupby('idgrupoescala')
            ->fetchArray();
        return $result;
	}

	/**
     * Obtener dado un identificador del grupo escalas sus salarios esclas.
     * 
     * @param int       $idgrupoescala Identificador del grupo escala.
     * @return array    Listado de los datos de los salarios escalas.
     */
    public static function obtenerSalariosEscalasByIdGrupoE($idgrupoescala) {

        //Devolviendo los salarios escalas en forma de arreglo.
        return Doctrine_Query::create()
        		->select('se.idsalarioescala, se.idgrupoescala, ge.denominacion as denominacion, se.idsectorsalarial, se.salario, se.fechainicio, se.fechafin')
                ->from('NomSalarioEscala se')
                ->leftJoin('se.NomGrupoEscala ge on ge.idgrupoescala = se.idgrupoescala')
                ->where('se.idgrupoescala = ?', $idgrupoescala)
                ->fetchArray();
    }
    
    /**
     * Obtener el salario dado el idgrupoescala y el idsector salarial.
     * 
     * @return int.
     */
    
    public static function obtenerSalariosEscalasByIdGrupoSector($idgrupoescala, $sectorsalarial) {
        //print_r($idgrupoescala);
       // print_r($sectorsalarial);die;
        //Devolviendo los salarios escalas en forma de arreglo.
        return Doctrine_Query::create()
        		->select('se.salario as salario')
                ->from('NomSalarioEscala se')
                ->leftJoin('se.NomGrupoEscala ge on ge.idgrupoescala = se.idgrupoescala')
                ->leftJoin('se.NomSectorSalarial ss on ss.idsectorsalarial = se.idsectorsalarial')
                ->where('se.idgrupoescala = ? and se.idsectorsalarial=?',array($idgrupoescala, $sectorsalarial))
                ->fetchOne()
                ->salario;
    }
    /**
     * Obtener el salario dado el idgrupoescala y el idsector salarial en la misma tabla
     *
     * @return int.
     */

    public static function obtenerSalario($idgrupoescala,$idsectorsalarial) {
        //print_r($idgrupoescala);
       // print_r($sectorsalarial);die;
        //Devolviendo los salarios escalas en forma de arreglo.
        return Doctrine_Query::create()
        		->select('se.salario as salario')
                ->from('NomSalarioEscala se')
                ->where('se.idgrupoescala = ? and se.idsectorsalarial=?',array($idgrupoescala, $idsectorsalarial))
                ->fetchOne()
                ->salario;
    }

	/**
     * Obtener la cantidad total de salarios escalas.
     * 
     * @return int      Cantidad total de salarios escalas.
     */
    public static function obtenerCantidadTotalSalariosEscalas() {

        //Devolviendo la cantidad total de salarios escalas.
        return Doctrine_Query::create()->select('COUNT(DISTINCT(idgrupoescala)) AS cantidad')
                        ->from('NomSalarioEscala')
                        ->fetchOne()
                        ->cantidad;
    }
	
    /**
     * Eliminar los salarios escalas dado un id de grupo escala.
     * 
     * @param int       $idgrupoescala Identificador del grupo escala.
     */
    public static function eliminarSalariosEscalasByIdGrupEsc($idgrupoescala) {
        
        //Eliminando los salarios escalas.
        Doctrine_Query::create()->delete()
            ->from('NomSalarioEscala')
            ->where("idgrupoescala = ?",$idgrupoescala)
            ->execute();
    }
	
	/**
     * Obtener si existe un salario escala.
     * 
	 * @param array $arraysectores    	Arreglo de sectores salariales.
     * @param int $idgrupoesc    	 	Identificador del grupo escala.
	 * @param array $idsalesc    	 	Arreglo de id de salarios escalas.
	 *
     * @return boolean    				Si existe un salario escala.
     */
    public static function existeSalarioEscala($arraysectores, $idgrupoesc, $idsalesc) {
		
		$query = Doctrine_Query::create()->select('COUNT(idsalarioescala) AS cantidad')
                        ->from('NomSalarioEscala')
						// ->whereNotIn('idsalarioescala', $idsalesc);
						->where("idgrupoescala = ?",$idgrupoesc);
			if(count($idsalesc)){
				$query->andWhereNotIn('idsalarioescala', $idsalesc);
			}			
						
						
						
						
		// if(count($idsalesc)){
			// $query->addWhere('idcausaexclusion <> ?', $idcausaexc);
		// }		
		
		return    $query->fetchOne()->cantidad;
		
    }
	
}
